    [5398]={name="Canopy Leggings",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'The Woodland Protector'. Pick it over the other reward choices.",zone="Shadowglen",questName="The Woodland Protector",lore="Something evil is brewing in the forests of Teldrassil. Look long the hills to where the peaceful furbolgs used to dwell. They have deserted their homes and are amassing under the name of the Gnarlpine tribe."},
    [5459]={name="Defender Axe",quality=2,ilvl=13,sourceType="quest_reward",instructions="Reward from the quest 'Ursal the Mauler'. Pick it over the other reward choices.",zone="Teldrassil",questName="Ursal the Mauler",lore="Now the time has come to save the Druids of the Talon. If we fail now, they will be forever lost in sleep. I shall prepare the Relics of Wakening and perform the ritual."},
    [5581]={name="Smooth Walking Staff",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'The Stolen Journal'. Pick it over the other reward choices.",zone="Coldridge Valley",questName="The Stolen Journal",lore="My journal! They took it away to the cave. The one that had it... It was a big brute with some odd markings on his skin and face. I didn't get a much better look than that."},
    [5587]={name="Thornroot Club",quality=2,ilvl=13,sourceType="quest_reward",instructions="Reward from the quest 'Ursal the Mauler'. Pick it over the other reward choices.",zone="Teldrassil",questName="Ursal the Mauler",lore="Now the time has come to save the Druids of the Talon. If we fail now, they will be forever lost in sleep. I shall prepare the Relics of Wakening and perform the ritual."},
    [5591]={name="Rain-spotted Cape",quality=1,ilvl=11,sourceType="quest_reward",instructions="Reward from the quest 'The Enchanted Glade'. Pick it over the other reward choices.",zone="Teldrassil",questName="The Enchanted Glade",lore="I was dispatched with a small group of Sentinels here to protect the Oracle Tree from the harpies that have made nests all around the glade."},
    [5617]={name="Vagabond Leggings",quality=2,ilvl=13,sourceType="quest_reward",instructions="Reward from the quest 'Bashal'Aran'. Pick it over the other reward choices.",zone="Darkshore",questName="Bashal'Aran",lore="It was the craft of one of the most powerful of the Highborne that created the seal that formed my prison. In Ameth'Aran, the ruins to the south that are twin to these, persists even today an ancient flame, blue in color."},
    [5777]={name="Brave's Axe",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'Rite of Strength'. Pick it over the other reward choices.",zone="Red Cloud Mesa",questName="Rite of Strength",lore="The Rites of the Earthmother are the steps a young tauren needs to take to gain respect in Thunder Bluff. First you must pass the Rite of Strength."},
    [5778]={name="Primitive Walking Stick",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'Vile Familiars'. Pick it over the other reward choices.",questName="Vile Familiars",lore="I trust the Valley of Trials will teach you much, young. I was sent to the Valley to guide you, but I have discovered a growing taint here..."},
    [5957]={name="Handstitched Leather Vest",quality=2,ilvl=8,reqLevel=3,sourceType="profession",instructions="Crafted with Leatherworking (requires skill 1).",profession="Leatherworking"},
    [6059]={name="Nomadic Vest",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'The Battleboars'.",zone="Red Cloud Mesa",questName="The Battleboars",lore="The Battleboars of Brambleblade Ravine to the east are encroaching on our tribal hunting grounds. They are trained to be malicious by the Bristleback Quilboars with whom we are at war."},
    [6070]={name="Wolfskin Bracers",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'Wolves Across the Border'. Pick it over the other reward choices.",zone="Northshire Valley",questName="Wolves Across the Border",lore="I hate those nasty timber wolves! But I sure like eating wolf steaks... Bring me tough wolf meat and I will exchange it for something you'll find useful."},
